// Writes src/assets.generated.ts: the Typst prelude and the CSS as string constants, so the
// package works in browsers and workers without fetching or bundler loaders. The files in
// typst/ and css/ are the sources; a test checks the generated module is current.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));

export const generate = () =>
  [
    "// Generated by scripts/embed.mjs from typst/html-compat.typ and css/html-compat.css. Don't edit.",
    "",
    `export const PRELUDE_SOURCE = ${JSON.stringify(readFileSync(`${root}typst/html-compat.typ`, "utf8"))};`,
    "",
    `export const CSS_SOURCE = ${JSON.stringify(readFileSync(`${root}css/html-compat.css`, "utf8"))};`,
    "",
  ].join("\n");

if (import.meta.url === `file://${process.argv[1]}`) {
  // Only when it changed: the build runs this while turbo may be type-checking the package, which
  // reads the file (a rewrite truncates it first, and tsc then saw an empty file, "not a module").
  const out = `${root}src/assets.generated.ts`;
  const text = generate();
  if (readFileSync(out, "utf8") !== text) writeFileSync(out, text);
}
